def check(s):
    st = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for i, ch in enumerate(s):
        if ch in '([{':
            st.append(ch)
        elif ch in pairs:
            if not st or st.pop() != pairs[ch]:
                return i
    return -1 if not st else len(s)

print(check('{[()()]}([)]'))
```

