from collections import deque

def f(q, k):
    st = []
    for _ in range(k):
        st.append(q.popleft())
    while st:
        q.append(st.pop())
    for _ in range(len(q) - k):
        q.append(q.popleft())
    return list(q)

print(f(deque([10, 20, 30, 40, 50, 60]), 4))
